{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SNITCH_SIZE_CHANNEL_CUTSIZE AS WITH eligible_skus AS ( SELECT DISTINCT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP FROM SNITCH_DB.MAPLEMONK.OMNI_BUFFER_SKUS WHERE UPPER(TRIM(SKU_GROUP)) LIKE \'4MBG%\' OR UPPER(TRIM(SKU_GROUP)) LIKE \'4B%\' ), size_master AS ( SELECT COLUMN1 AS SIZE_LABEL FROM VALUES (\'40/3XL\'), (\'42/4XL\'), (\'44/5XL\'), (\'46/6XL\'), (\'48/7XL\'), (\'50/8XL\') ), cut_size_master AS ( SELECT COLUMN1 AS SIZE_LABEL FROM VALUES (\'40/3XL\'), (\'42/4XL\'), (\'44/5XL\'), (\'46/6XL\') ), latest_question_records AS ( SELECT * FROM SNITCH_DB.MAPLEMONK.QUESTION_2190 QUALIFY ROW_NUMBER() OVER ( PARTITION BY _AIRBYTE_QUESTION_2190_HASHID ORDER BY _AIRBYTE_NORMALIZED_AT DESC NULLS LAST, _AIRBYTE_EMITTED_AT DESC NULLS LAST ) = 1 ), question_normalized AS ( SELECT REGEXP_REPLACE( UPPER(TRIM(q.SKU)), \'-[^-]+$\', \'\' ) AS SKU_GROUP, q.BRANCH_CODE, CASE WHEN REGEXP_SUBSTR(UPPER(TRIM(q.SKU)), \'[^-]+$\') IN (\'3XL\', \'40\') THEN \'40/3XL\' WHEN REGEXP_SUBSTR(UPPER(TRIM(q.SKU)), \'[^-]+$\') IN (\'4XL\', \'42\') THEN \'42/4XL\' WHEN REGEXP_SUBSTR(UPPER(TRIM(q.SKU)), \'[^-]+$\') IN (\'5XL\', \'44\') THEN \'44/5XL\' WHEN REGEXP_SUBSTR(UPPER(TRIM(q.SKU)), \'[^-]+$\') IN (\'6XL\', \'46\') THEN \'46/6XL\' WHEN REGEXP_SUBSTR(UPPER(TRIM(q.SKU)), \'[^-]+$\') IN (\'7XL\', \'48\') THEN \'48/7XL\' WHEN REGEXP_SUBSTR(UPPER(TRIM(q.SKU)), \'[^-]+$\') IN (\'8XL\', \'50\') THEN \'50/8XL\' END AS SIZE_LABEL, UPPER(TRIM(q.LOCATION)) AS LOCATION, COALESCE( TRY_TO_NUMBER(TO_VARCHAR(q.INVENTORY_TOTAL)), 0 ) AS INVENTORY FROM latest_question_records q JOIN eligible_skus e ON REGEXP_REPLACE( UPPER(TRIM(q.SKU)), \'-[^-]+$\', \'\' ) = e.SKU_GROUP WHERE UPPER(TRIM(q.LOCATION)) LIKE \'BOH-%\' OR UPPER(TRIM(q.LOCATION)) LIKE \'BOHQ-%\' ), channel_inventory AS ( SELECT SKU_GROUP, SIZE_LABEL, SUM( CASE WHEN LOCATION LIKE \'BOH-%\' AND LOCATION NOT LIKE \'BOHQ-%\' THEN INVENTORY ELSE 0 END ) AS OMNI_INVENTORY, SUM( CASE WHEN LOCATION LIKE \'BOHQ-%\' THEN INVENTORY ELSE 0 END ) AS QUICK_INVENTORY FROM question_normalized WHERE SIZE_LABEL IS NOT NULL GROUP BY SKU_GROUP, SIZE_LABEL ), warehouse_raw AS ( SELECT UPPER(TRIM(\"Item SkuCode\")) AS ITEM_SKU, UPPER(TRIM(FACILITY)) AS WAREHOUSE, COALESCE( NULLIF(UPPER(TRIM(SIZE)), \'\'), REGEXP_SUBSTR( UPPER(TRIM(\"Item SkuCode\")), \'[^-]+$\' ) ) AS SIZE_TOKEN, \"Category Name\" AS CATEGORY_NAME, COALESCE( TRY_TO_NUMBER(TO_VARCHAR(INVENTORY)), 0 ) AS INVENTORY, \"DATE\" AS SNAPSHOT_DATE FROM SNITCH_DB.MAPLEMONK.SNITCH_FINAL_INVENTORY_WH2 WHERE UPPER(TRIM(\"Item SkuCode\")) LIKE \'4MBG%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'4B%\' ), warehouse_normalized AS ( SELECT CASE WHEN ITEM_SKU LIKE \'%-\' || SIZE_TOKEN THEN REGEXP_REPLACE(ITEM_SKU, \'-[^-]+$\', \'\') ELSE ITEM_SKU END AS SKU_GROUP, WAREHOUSE, CASE WHEN SIZE_TOKEN IN (\'3XL\', \'40\') THEN \'40/3XL\' WHEN SIZE_TOKEN IN (\'4XL\', \'42\') THEN \'42/4XL\' WHEN SIZE_TOKEN IN (\'5XL\', \'44\') THEN \'44/5XL\' WHEN SIZE_TOKEN IN (\'6XL\', \'46\') THEN \'46/6XL\' WHEN SIZE_TOKEN IN (\'7XL\', \'48\') THEN \'48/7XL\' WHEN SIZE_TOKEN IN (\'8XL\', \'50\') THEN \'50/8XL\' END AS SIZE_LABEL, CATEGORY_NAME, INVENTORY, SNAPSHOT_DATE FROM warehouse_raw ), latest_warehouse_date AS ( SELECT MAX(SNAPSHOT_DATE) AS SNAPSHOT_DATE FROM warehouse_normalized ), warehouse_inventory AS ( SELECT w.SKU_GROUP, w.WAREHOUSE, w.SIZE_LABEL, MAX(w.CATEGORY_NAME) AS CATEGORY_NAME, SUM(w.INVENTORY) AS WAREHOUSE_INVENTORY FROM warehouse_normalized w JOIN latest_warehouse_date d ON w.SNAPSHOT_DATE = d.SNAPSHOT_DATE WHERE w.SIZE_LABEL IS NOT NULL GROUP BY w.SKU_GROUP, w.WAREHOUSE, w.SIZE_LABEL ), warehouse_sku_grid AS ( SELECT e.SKU_GROUP, w.WAREHOUSE, s.SIZE_LABEL FROM eligible_skus e CROSS JOIN ( SELECT DISTINCT WAREHOUSE FROM warehouse_inventory ) w CROSS JOIN size_master s ), size_level AS ( SELECT g.SKU_GROUP, g.WAREHOUSE, g.SIZE_LABEL, COALESCE(w.CATEGORY_NAME, \'\') AS CATEGORY_NAME, COALESCE(w.WAREHOUSE_INVENTORY, 0) AS WAREHOUSE_INVENTORY, COALESCE(c.OMNI_INVENTORY, 0) AS OMNI_INVENTORY, COALESCE(c.QUICK_INVENTORY, 0) AS QUICK_INVENTORY, COALESCE(w.WAREHOUSE_INVENTORY, 0) + COALESCE(c.OMNI_INVENTORY, 0) + COALESCE(c.QUICK_INVENTORY, 0) AS WAREHOUSE_OMNI_QUICK_INVENTORY, COALESCE(c.OMNI_INVENTORY, 0) + COALESCE(c.QUICK_INVENTORY, 0) AS OMNI_QUICK_INVENTORY FROM warehouse_sku_grid g LEFT JOIN warehouse_inventory w ON g.SKU_GROUP = w.SKU_GROUP AND g.WAREHOUSE = w.WAREHOUSE AND g.SIZE_LABEL = w.SIZE_LABEL LEFT JOIN channel_inventory c ON g.SKU_GROUP = c.SKU_GROUP AND g.SIZE_LABEL = c.SIZE_LABEL ), cut_size_evaluation AS ( SELECT d.* FROM size_level d INNER JOIN cut_size_master c ON d.SIZE_LABEL = c.SIZE_LABEL ), sku_status AS ( SELECT SKU_GROUP, WAREHOUSE, MAX(CATEGORY_NAME) AS CATEGORY_NAME, CASE WHEN COUNT_IF(WAREHOUSE_INVENTORY = 0) > 0 THEN \'CUT SIZE\' ELSE \'FULL SIZE\' END AS WAREHOUSE_CUT_SIZE_STATUS, CASE WHEN COUNT_IF( WAREHOUSE_OMNI_QUICK_INVENTORY = 0 ) > 0 THEN \'CUT SIZE\' ELSE \'FULL SIZE\' END AS WAREHOUSE_OMNI_QUICK_CUT_SIZE_STATUS, CASE WHEN COUNT_IF(OMNI_QUICK_INVENTORY = 0) > 0 THEN \'CUT SIZE\' ELSE \'FULL SIZE\' END AS OMNI_QUICK_CUT_SIZE_STATUS FROM cut_size_evaluation GROUP BY SKU_GROUP, WAREHOUSE ) SELECT d.SKU_GROUP, d.WAREHOUSE, d.SIZE_LABEL, d.CATEGORY_NAME, d.WAREHOUSE_INVENTORY, d.OMNI_INVENTORY, d.QUICK_INVENTORY, d.WAREHOUSE_OMNI_QUICK_INVENTORY, d.OMNI_QUICK_INVENTORY, s.WAREHOUSE_CUT_SIZE_STATUS, s.OMNI_QUICK_CUT_SIZE_STATUS, s.WAREHOUSE_OMNI_QUICK_CUT_SIZE_STATUS FROM size_level d JOIN sku_status s ON d.SKU_GROUP = s.SKU_GROUP AND d.WAREHOUSE = s.WAREHOUSE ORDER BY d.WAREHOUSE, d.SKU_GROUP, d.SIZE_LABEL;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            